public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }

    if (file.isFile() || !file.isDirectory()) {
        // For regular files or non-directory (e.g., symlink), just register for deletion.
        file.deleteOnExit();
        return;
    }

    // For directories, we need to register all nested files first, then the directories.
    Deque<File> stack = new ArrayDeque<>();
    stack.push(file);
    List<File> dirs = new ArrayList<>();

    while (!stack.isEmpty()) {
        File current = stack.pop();
        if (current.isDirectory()) {
            dirs.add(current);
            File[] children = current.listFiles();
            if (children == null) {
                throw new IOException("Unable to list contents of directory: " + current);
            }
            for (File child : children) {
                if (child.isDirectory()) {
                    stack.push(child);
                } else {
                    child.deleteOnExit();
                }
            }
        } else {
            current.deleteOnExit();
        }
    }

    // Register directories for deletion in reverse order so that children are deleted first.
    for (int i = dirs.size() - 1; i >= 0; i--) {
        dirs.get(i).deleteOnExit();
    }
